children.text:
@font-face {
    font-family: 'Roboto';
    src: url('../font/Roboto-Regular.ttf') format('truetype');
    font-weight: normal;
    font-style: normal;
}

body {
    font-family: 'Roboto', 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
    font-size: 16px;
    line-height: 1.6;
    margin: 20px;
    background-color: #fafafa;
    color: #212121;
}

.test-container {
    max-width: 600px;
    padding: 24px;
    background-color: white;
    border-radius: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.material-heading {
    color: #1976d2;
    font-size: 28px;
    font-weight: 400;
    margin-bottom: 16px;
}

.card-content {
    background-color: #f5f5f5;
    padding: 16px;
    border-radius: 4px;
    margin: 16px 0;
    border-left: 4px solid #2196f3;
}

.caption-text {
    font-size: 12px;
    color: #757575;
    margin-top: 8px;
}
